package solution

import (
	"sync"
	"testing"
)

func TestChronoIDLayoutAndSequence(t *testing.T) {
	g, err := NewChronoID(513, 1000)
	if err != nil {
		t.Fatal(err)
	}
	for sequence := uint64(0); sequence < 3; sequence++ {
		got, err := g.Next(1007)
		if err != nil {
			t.Fatalf("Next failed: %v", err)
		}
		want := (uint64(7) << 22) | (uint64(513) << 12) | sequence
		if got != want {
			t.Fatalf("ID = %d, want %d", got, want)
		}
	}
	got, err := g.Next(1008)
	if err != nil {
		t.Fatal(err)
	}
	want := (uint64(8) << 22) | (uint64(513) << 12)
	if got != want {
		t.Fatalf("new millisecond ID = %d, want %d", got, want)
	}
}

func TestChronoIDConstructorAndNilReceiverErrors(t *testing.T) {
	if _, err := NewChronoID(1023, -50); err != nil {
		t.Fatalf("maximum node should be valid: %v", err)
	}
	if _, err := NewChronoID(1024, 0); err == nil {
		t.Fatal("node 1024 should be rejected")
	}
	var g *ChronoID
	if _, err := g.Next(0); err == nil {
		t.Fatal("nil receiver should return an error")
	}
}

func TestChronoIDTimestampBoundsAndFailureAtomicity(t *testing.T) {
	const maxDelta = int64((1 << 41) - 1)
	g, err := NewChronoID(1, 10)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := g.Next(9); err == nil {
		t.Fatal("timestamp before epoch accepted")
	}
	first, err := g.Next(10)
	if err != nil {
		t.Fatal(err)
	}
	if first != uint64(1)<<12 {
		t.Fatalf("first ID = %d", first)
	}
	if _, err := g.Next(9); err == nil {
		t.Fatal("regressing timestamp accepted")
	}
	second, err := g.Next(10)
	if err != nil {
		t.Fatal(err)
	}
	if second != first+1 {
		t.Fatalf("failed call changed sequence state: first=%d second=%d", first, second)
	}

	boundary, err := g.Next(10 + maxDelta)
	if err != nil {
		t.Fatalf("maximum delta rejected: %v", err)
	}
	wantBoundary := (uint64(maxDelta) << 22) | (uint64(1) << 12)
	if boundary != wantBoundary {
		t.Fatalf("boundary ID = %d, want %d", boundary, wantBoundary)
	}
	if _, err := g.Next(10 + maxDelta + 1); err == nil {
		t.Fatal("delta above 41 bits accepted")
	}
	next, err := g.Next(10 + maxDelta)
	if err != nil {
		t.Fatalf("valid request after overflow error failed: %v", err)
	}
	if next != boundary+1 {
		t.Fatalf("overflow error changed state: boundary=%d next=%d", boundary, next)
	}
}

func TestChronoIDSequenceExhaustionAndRecovery(t *testing.T) {
	g, err := NewChronoID(0, 0)
	if err != nil {
		t.Fatal(err)
	}
	for sequence := uint64(0); sequence <= 4095; sequence++ {
		got, err := g.Next(3)
		if err != nil {
			t.Fatalf("sequence %d failed: %v", sequence, err)
		}
		want := (uint64(3) << 22) | sequence
		if got != want {
			t.Fatalf("sequence %d produced %d, want %d", sequence, got, want)
		}
	}
	if _, err := g.Next(3); err == nil {
		t.Fatal("4097th request in a millisecond succeeded")
	}
	got, err := g.Next(4)
	if err != nil {
		t.Fatalf("next millisecond failed: %v", err)
	}
	if want := uint64(4) << 22; got != want {
		t.Fatalf("sequence did not reset: got %d, want %d", got, want)
	}
}

func TestChronoIDConcurrentCallsAreUniqueAndContiguous(t *testing.T) {
	const count = 256
	g, err := NewChronoID(7, 100)
	if err != nil {
		t.Fatal(err)
	}
	ids := make(chan uint64, count)
	errs := make(chan error, count)
	var wg sync.WaitGroup
	for i := 0; i < count; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			id, err := g.Next(105)
			if err != nil {
				errs <- err
				return
			}
			ids <- id
		}()
	}
	wg.Wait()
	close(ids)
	close(errs)
	for err := range errs {
		t.Fatalf("concurrent Next failed: %v", err)
	}
	seen := make(map[uint64]bool, count)
	base := (uint64(5) << 22) | (uint64(7) << 12)
	for id := range ids {
		if id < base || id >= base+count {
			t.Fatalf("ID outside contiguous range: %d", id)
		}
		if seen[id] {
			t.Fatalf("duplicate ID: %d", id)
		}
		seen[id] = true
	}
	if len(seen) != count {
		t.Fatalf("got %d unique IDs, want %d", len(seen), count)
	}
}

package solution

import "testing"

func TestReviewDeltaOverflow0095(t *testing.T) {
	const minimum int64 = -1 << 63
	const maximum int64 = 1<<63 - 1
	g, err := NewChronoID(0, minimum)
	if err != nil { t.Fatal(err) }
	if id, err := g.Next(maximum); err == nil {
		t.Fatalf("delta greater than 41 bits accepted: id=%d", id)
	}
	if id, err := g.Next(minimum); err != nil || id != 0 {
		t.Fatalf("valid first timestamp after rejection: id=%d err=%v", id, err)
	}
}

